create table public.chainlab_step_settings (
  step_id uuid primary key references public.prompt_chain_steps(id) on delete cascade,
  name text not null check(char_length(btrim(name)) between 1 and 120),
  kind text not null check(kind in ('text','image')),
  fallback_model text not null check(char_length(fallback_model) between 1 and 200),
  updated_at timestamptz not null default now()
);
alter table public.chainlab_step_settings enable row level security;
revoke all on public.chainlab_step_settings from public,anon,authenticated;

create function public.chainlab_list_chains()
returns jsonb language plpgsql stable security definer set search_path=''
as $$
begin
  if public.chainlab_is_superadmin() is not true then raise exception 'Superadmin access required' using errcode='42501'; end if;
  return jsonb_build_object(
    'chains',coalesce((select jsonb_agg(to_jsonb(c) order by c.id) from public.prompt_chains c),'[]'::jsonb),
    'steps',coalesce((select jsonb_agg(to_jsonb(s) order by s.chain_id,s.position) from public.prompt_chain_steps s),'[]'::jsonb),
    'settings',coalesce((select jsonb_agg(to_jsonb(t) order by t.step_id) from public.chainlab_step_settings t),'[]'::jsonb)
  );
end;
$$;

create function public.chainlab_get_chain(p_id uuid)
returns jsonb language plpgsql stable security definer set search_path=''
as $$
declare v_result jsonb;
begin
  if public.chainlab_is_superadmin() is not true then raise exception 'Superadmin access required' using errcode='42501'; end if;
  select jsonb_build_object(
    'chain',to_jsonb(c),
    'steps',coalesce((select jsonb_agg(to_jsonb(s) order by s.position) from public.prompt_chain_steps s where s.chain_id=c.id),'[]'::jsonb),
    'settings',coalesce((select jsonb_agg(to_jsonb(t) order by t.step_id) from public.chainlab_step_settings t join public.prompt_chain_steps s on s.id=t.step_id where s.chain_id=c.id),'[]'::jsonb)
  ) into v_result from public.prompt_chains c where c.id=p_id;
  if not found then raise exception 'Prompt chain not found' using errcode='P0002'; end if;
  return v_result;
end;
$$;

create function public.chainlab_create_chain(p_name text,p_description text,p_is_active boolean)
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_id uuid;
begin
  if public.chainlab_is_superadmin() is not true then raise exception 'Superadmin access required' using errcode='42501'; end if;
  if p_name is null or char_length(btrim(p_name)) not between 1 and 120
     or p_description is null or char_length(p_description)>2000 or p_is_active is null then
    raise exception 'Invalid prompt chain fields' using errcode='22023';
  end if;
  insert into public.prompt_chains(name,description,is_active) values(btrim(p_name),p_description,p_is_active) returning id into v_id;
  return public.chainlab_get_chain(v_id);
end;
$$;

create function public.chainlab_update_chain(p_id uuid,p_patch jsonb)
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_chain public.prompt_chains;
begin
  if public.chainlab_is_superadmin() is not true then raise exception 'Superadmin access required' using errcode='42501'; end if;
  select * into v_chain from public.prompt_chains where id=p_id for update;
  if not found then raise exception 'Prompt chain not found' using errcode='P0002'; end if;
  if p_patch is null or jsonb_typeof(p_patch)<>'object' or p_patch='{}'::jsonb
     or exists(select 1 from jsonb_object_keys(p_patch) k where k not in ('name','description','is_active')) then
    raise exception 'Supply only editable chain fields' using errcode='22023';
  end if;
  if p_patch?'name' then
    if jsonb_typeof(p_patch->'name')<>'string' or char_length(btrim(p_patch->>'name')) not between 1 and 120 then raise exception 'Invalid chain name' using errcode='22023'; end if;
    v_chain.name:=btrim(p_patch->>'name');
  end if;
  if p_patch?'description' then
    if jsonb_typeof(p_patch->'description')<>'string' or char_length(p_patch->>'description')>2000 then raise exception 'Invalid chain description' using errcode='22023'; end if;
    v_chain.description:=p_patch->>'description';
  end if;
  if p_patch?'is_active' then
    if jsonb_typeof(p_patch->'is_active')<>'boolean' then raise exception 'Invalid active flag' using errcode='22023'; end if;
    v_chain.is_active:=(p_patch->>'is_active')::boolean;
  end if;
  update public.prompt_chains set name=v_chain.name,description=v_chain.description,is_active=v_chain.is_active,updated_at=now() where id=p_id;
  return public.chainlab_get_chain(p_id);
end;
$$;

create function public.chainlab_delete_chain(p_id uuid)
returns void language plpgsql security definer set search_path=''
as $$
begin
  if public.chainlab_is_superadmin() is not true then raise exception 'Superadmin access required' using errcode='42501'; end if;
  perform 1 from public.prompt_chains where id=p_id for update;
  if not found then raise exception 'Prompt chain not found' using errcode='P0002'; end if;
  perform 1 from public.prompt_chain_steps where chain_id=p_id order by position,id for update;
  delete from public.prompt_chain_steps where chain_id=p_id;
  -- Existing RESTRICT references remain authoritative. Any failure rolls back
  -- the preceding step deletion and the sidecar's cascading deletion.
  delete from public.prompt_chains where id=p_id;
end;
$$;

create function public.chainlab_update_step(p_chain_id uuid,p_step_id uuid,p_step jsonb,p_settings jsonb)
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_step public.prompt_chain_steps; v_settings public.chainlab_step_settings;
begin
  if public.chainlab_is_superadmin() is not true then raise exception 'Superadmin access required' using errcode='42501'; end if;
  perform 1 from public.prompt_chains where id=p_chain_id for update;
  if not found then raise exception 'Prompt chain not found' using errcode='P0002'; end if;
  perform 1 from public.prompt_chain_steps where chain_id=p_chain_id order by position,id for update;
  select * into v_step from public.prompt_chain_steps where id=p_step_id and chain_id=p_chain_id;
  if not found then raise exception 'Prompt chain step not found' using errcode='P0002'; end if;
  p_step:=coalesce(p_step,'{}'::jsonb); p_settings:=coalesce(p_settings,'{}'::jsonb);
  if jsonb_typeof(p_step)<>'object' or jsonb_typeof(p_settings)<>'object'
     or exists(select 1 from jsonb_object_keys(p_step) k where k not in ('role','template','model_id'))
     or exists(select 1 from jsonb_object_keys(p_settings) k where k not in ('name','kind','fallback_model')) then
    raise exception 'Invalid step or display settings fields' using errcode='22023';
  end if;
  if p_step?'role' then
    if jsonb_typeof(p_step->'role')<>'string' or p_step->>'role' not in ('system','user','assistant') then raise exception 'Invalid prompt role' using errcode='22023'; end if;
    v_step.role:=p_step->>'role';
  end if;
  if p_step?'template' then
    if jsonb_typeof(p_step->'template')<>'string' or char_length(p_step->>'template') not between 1 and 2000 then raise exception 'Prompt template must contain 1 to 2000 characters' using errcode='22023'; end if;
    v_step.template:=p_step->>'template';
  end if;
  if p_step?'model_id' then
    if jsonb_typeof(p_step->'model_id')='null' then v_step.model_id:=null;
    elsif jsonb_typeof(p_step->'model_id')='string' then
      begin v_step.model_id:=(p_step->>'model_id')::uuid;
      exception when invalid_text_representation then raise exception 'Invalid model UUID' using errcode='22023'; end;
    else raise exception 'Invalid model UUID' using errcode='22023'; end if;
  end if;
  select * into v_settings from public.chainlab_step_settings where step_id=p_step_id;
  if not found then v_settings.name:='Step '||v_step.position;v_settings.kind:='text';v_settings.fallback_model:='gpt-4.1-mini';end if;
  if p_settings?'name' then
    if jsonb_typeof(p_settings->'name')<>'string' then raise exception 'Invalid step name' using errcode='22023';end if;
    v_settings.name:=btrim(p_settings->>'name');
  end if;
  if p_settings?'kind' then
    if jsonb_typeof(p_settings->'kind')<>'string' then raise exception 'Invalid output kind' using errcode='22023';end if;
    v_settings.kind:=p_settings->>'kind';
  end if;
  if p_settings?'fallback_model' then
    if jsonb_typeof(p_settings->'fallback_model')<>'string' then raise exception 'Invalid fallback model' using errcode='22023';end if;
    -- Registry assignments remain authoritative, including inactive or
    -- unsupported providers. An unresolved UI label must not rewrite the UUID
    -- or prevent editing the existing prompt.
    if v_step.model_id is null then v_settings.fallback_model:=p_settings->>'fallback_model';end if;
  end if;
  if char_length(btrim(v_settings.name)) not between 1 and 120 or v_settings.kind not in ('text','image')
     or char_length(v_settings.fallback_model) not between 1 and 200 then raise exception 'Invalid step display settings' using errcode='22023';end if;
  if v_step.model_id is null and not (
    (v_settings.kind='text' and v_settings.fallback_model in ('gpt-4.1-mini','gpt-4.1','gpt-4o-mini'))
    or (v_settings.kind='image' and v_settings.fallback_model='gpt-image-1')
  ) then raise exception 'Choose a supported fallback model when no registry model is assigned' using errcode='22023';end if;
  update public.prompt_chain_steps set role=v_step.role,template=v_step.template,model_id=v_step.model_id,updated_at=now() where id=p_step_id returning * into v_step;
  insert into public.chainlab_step_settings(step_id,name,kind,fallback_model)
  values(p_step_id,v_settings.name,v_settings.kind,v_settings.fallback_model)
  on conflict(step_id) do update set name=excluded.name,kind=excluded.kind,fallback_model=excluded.fallback_model,updated_at=now()
  returning * into v_settings;
  update public.prompt_chains set updated_at=now() where id=p_chain_id;
  return jsonb_build_object('step',to_jsonb(v_step),'settings',to_jsonb(v_settings));
end;
$$;

create function public.chainlab_append_step(p_chain_id uuid,p_step jsonb,p_settings jsonb)
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_count integer;v_position integer:=1;v_existing record;v_step public.prompt_chain_steps;v_role text:='user';v_template text;v_model uuid;
begin
  if public.chainlab_is_superadmin() is not true then raise exception 'Superadmin access required' using errcode='42501';end if;
  perform 1 from public.prompt_chains where id=p_chain_id for update;
  if not found then raise exception 'Prompt chain not found' using errcode='P0002';end if;
  perform 1 from public.prompt_chain_steps where chain_id=p_chain_id order by position,id for update;
  p_step:=coalesce(p_step,'{}'::jsonb);
  if jsonb_typeof(p_step)<>'object' or exists(select 1 from jsonb_object_keys(p_step) k where k not in ('role','template','model_id')) then raise exception 'Invalid step fields' using errcode='22023';end if;
  if p_step?'role' then
    if jsonb_typeof(p_step->'role')<>'string' or p_step->>'role' not in ('system','user','assistant') then raise exception 'Invalid prompt role' using errcode='22023';end if;
    v_role:=p_step->>'role';
  end if;
  if not p_step?'template' or jsonb_typeof(p_step->'template')<>'string' or char_length(p_step->>'template') not between 1 and 2000 then raise exception 'Prompt template must contain 1 to 2000 characters' using errcode='22023';end if;
  v_template:=p_step->>'template';
  if p_step?'model_id' and jsonb_typeof(p_step->'model_id')<>'null' then
    if jsonb_typeof(p_step->'model_id')<>'string' then raise exception 'Invalid model UUID' using errcode='22023';end if;
    begin v_model:=(p_step->>'model_id')::uuid;
    exception when invalid_text_representation then raise exception 'Invalid model UUID' using errcode='22023';end;
  end if;
  select count(*) into v_count from public.prompt_chain_steps where chain_id=p_chain_id;
  if v_count>=1000 then raise exception 'This chain has reached the 1000-step position limit' using errcode='22023';end if;
  -- An ascending compaction only moves rows into empty lower slots, preserving
  -- the existing immediate unique constraint and positive position check.
  for v_existing in select id,position from public.prompt_chain_steps where chain_id=p_chain_id order by position,id loop
    if v_existing.position<>v_position then update public.prompt_chain_steps set position=v_position,updated_at=now() where id=v_existing.id;end if;
    v_position:=v_position+1;
  end loop;
  insert into public.prompt_chain_steps(chain_id,position,role,template,model_id)
  values(p_chain_id,v_count+1,v_role,v_template,v_model) returning * into v_step;
  -- The shared update path validates settings and writes them atomically with
  -- the inserted step. An invalid setting rolls back compaction and insertion.
  return public.chainlab_update_step(p_chain_id,v_step.id,'{}'::jsonb,p_settings);
end;
$$;

create function public.chainlab_delete_step(p_chain_id uuid,p_step_id uuid)
returns void language plpgsql security definer set search_path=''
as $$
declare v_position integer:=1;v_existing record;
begin
  if public.chainlab_is_superadmin() is not true then raise exception 'Superadmin access required' using errcode='42501';end if;
  perform 1 from public.prompt_chains where id=p_chain_id for update;
  if not found then raise exception 'Prompt chain not found' using errcode='P0002';end if;
  perform 1 from public.prompt_chain_steps where chain_id=p_chain_id order by position,id for update;
  delete from public.prompt_chain_steps where chain_id=p_chain_id and id=p_step_id;
  if not found then raise exception 'Prompt chain step not found' using errcode='P0002';end if;
  for v_existing in select id,position from public.prompt_chain_steps where chain_id=p_chain_id order by position,id loop
    if v_existing.position<>v_position then update public.prompt_chain_steps set position=v_position,updated_at=now() where id=v_existing.id;end if;
    v_position:=v_position+1;
  end loop;
  update public.prompt_chains set updated_at=now() where id=p_chain_id;
end;
$$;

create function public.chainlab_reorder_steps(p_chain_id uuid,p_step_ids uuid[])
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_count integer;v_current uuid[];v_desired uuid;v_at_target uuid;v_free integer;v_position integer:=1;
begin
  if public.chainlab_is_superadmin() is not true then raise exception 'Superadmin access required' using errcode='42501';end if;
  perform 1 from public.prompt_chains where id=p_chain_id for update;
  if not found then raise exception 'Prompt chain not found' using errcode='P0002';end if;
  perform 1 from public.prompt_chain_steps where chain_id=p_chain_id order by position,id for update;
  select count(*),coalesce(array_agg(id order by position,id),array[]::uuid[]) into v_count,v_current from public.prompt_chain_steps where chain_id=p_chain_id;
  if p_step_ids is null or cardinality(p_step_ids)<>v_count
     or (select count(distinct id) from unnest(p_step_ids) ids(id))<>v_count
     or exists(select 1 from unnest(p_step_ids) ids(id) where not exists(select 1 from public.prompt_chain_steps s where s.chain_id=p_chain_id and s.id=ids.id)) then
    raise exception 'Step IDs must contain every current step exactly once' using errcode='22023';end if;
  if v_count=1000 then
    if v_current=p_step_ids then update public.prompt_chains set updated_at=now() where id=p_chain_id;return public.chainlab_get_chain(p_chain_id);end if;
    raise exception 'Reordering 1000 occupied positions needs a free slot; remove a step first' using errcode='22023';
  end if;
  foreach v_desired in array p_step_ids loop
    select id into v_at_target from public.prompt_chain_steps where chain_id=p_chain_id and position=v_position;
    if v_at_target is distinct from v_desired then
      if v_at_target is not null then
        select candidate into v_free from generate_series(1,1000) candidate
        where not exists(select 1 from public.prompt_chain_steps s where s.chain_id=p_chain_id and s.position=candidate)
        order by candidate limit 1;
        if v_free is null then raise exception 'No free step position is available' using errcode='22023';end if;
        update public.prompt_chain_steps set position=v_free,updated_at=now() where id=v_at_target;
      end if;
      update public.prompt_chain_steps set position=v_position,updated_at=now() where id=v_desired;
    end if;
    v_position:=v_position+1;
  end loop;
  update public.prompt_chains set updated_at=now() where id=p_chain_id;
  return public.chainlab_get_chain(p_chain_id);
end;
$$;

revoke all on function public.chainlab_list_chains(),public.chainlab_get_chain(uuid),public.chainlab_create_chain(text,text,boolean),public.chainlab_update_chain(uuid,jsonb),public.chainlab_delete_chain(uuid),public.chainlab_append_step(uuid,jsonb,jsonb),public.chainlab_update_step(uuid,uuid,jsonb,jsonb),public.chainlab_delete_step(uuid,uuid),public.chainlab_reorder_steps(uuid,uuid[]) from public,anon;
grant execute on function public.chainlab_list_chains(),public.chainlab_get_chain(uuid),public.chainlab_create_chain(text,text,boolean),public.chainlab_update_chain(uuid,jsonb),public.chainlab_delete_chain(uuid),public.chainlab_append_step(uuid,jsonb,jsonb),public.chainlab_update_step(uuid,uuid,jsonb,jsonb),public.chainlab_delete_step(uuid,uuid),public.chainlab_reorder_steps(uuid,uuid[]) to authenticated;
notify pgrst,'reload schema';


-- Read the existing assignment model registry without exposing provider configuration.

select pg_advisory_xact_lock(hashtext('chainlab:model-registry-install'));
do $guard$
declare v_column record;
begin
  if not exists (
    select 1 from pg_proc
    where oid=to_regprocedure('public.chainlab_is_superadmin()')
      and prorettype='boolean'::regtype and pronargs=0
  ) then
    raise exception 'The no-argument Boolean Chainlab superadmin predicate is required';
  end if;
  if exists (
    select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.proname='chainlab_list_models'
  ) then
    raise exception 'chainlab_list_models already exists; installation aborted without replacing it';
  end if;
  if not exists(select 1 from pg_class where oid=to_regclass('public.llm_models') and relkind in ('r','p'))
     or not exists(select 1 from pg_class where oid=to_regclass('public.llm_providers') and relkind in ('r','p')) then
    raise exception 'The existing public model and provider registry tables are required';
  end if;
  for v_column in
    select * from (values
      ('public.llm_models','id','uuid'),
      ('public.llm_models','provider_id','uuid'),
      ('public.llm_models','name','text'),
      ('public.llm_models','model_key','text'),
      ('public.llm_models','is_active','boolean'),
      ('public.llm_providers','id','uuid'),
      ('public.llm_providers','slug','text'),
      ('public.llm_providers','is_active','boolean')
    ) as required(table_name,column_name,type_name)
  loop
    if not exists (
      select 1 from pg_attribute
      where attrelid=to_regclass(v_column.table_name)
        and attname=v_column.column_name and attnum>0 and not attisdropped
        and atttypid=to_regtype(v_column.type_name)
    ) then
      raise exception 'Existing registry %.% is missing or has an incompatible type',v_column.table_name,v_column.column_name;
    end if;
  end loop;
end;
$guard$;

create function public.chainlab_list_models()
returns jsonb language plpgsql stable security definer set search_path=''
as $$
begin
  if public.chainlab_is_superadmin() is not true then
    raise exception 'Superadmin access required' using errcode='42501';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id',m.id,
      'label',coalesce(nullif(btrim(m.name),''),nullif(btrim(m.model_key),''),'Unnamed model'),
      'model',coalesce(m.model_key,''),
      'provider',lower(coalesce(p.slug,'')),
      'kind',case
        when m.model_key='gpt-image-1' then 'image'
        when m.model_key in ('gpt-4.1-mini','gpt-4.1','gpt-4o-mini') then 'text'
        else null
      end,
      'active',m.is_active is true and p.is_active is true
    ) order by lower(coalesce(p.slug,'')),coalesce(m.name,''),m.id)
    from public.llm_models m
    left join public.llm_providers p on p.id=m.provider_id
  ),'[]'::jsonb);
end;
$$;

revoke all on function public.chainlab_list_models() from public,anon;
grant execute on function public.chainlab_list_models() to authenticated;
notify pgrst,'reload schema';


-- App-owned history and private media only. Existing assignment history,
-- model rows, profile policies, storage buckets and storage guards are preserved.

select pg_advisory_xact_lock(hashtext('chainlab:history-install'));
do $guard$
begin
  if to_regprocedure('public.chainlab_is_superadmin()') is null
     or to_regclass('public.prompt_chains') is null then
    raise exception 'Install Chainlab authorization and the existing assignment schema first';
  end if;
  if to_regclass('public.chainlab_runs') is not null then
    raise exception 'chainlab_runs already exists; installation aborted without adopting it';
  end if;
  if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.proname in ('chainlab_list_runs','chainlab_create_run','chainlab_update_run','chainlab_can_access_media')) then
    raise exception 'A Chainlab history function already exists; installation aborted without replacing it';
  end if;
  if to_regclass('storage.buckets') is null or to_regclass('storage.objects') is null then
    raise exception 'Supabase Storage is required for private Chainlab media';
  end if;
  if exists(select 1 from storage.buckets where id='chainlab-generated-media' or name='chainlab-generated-media') then
    raise exception 'The Chainlab media bucket already exists; installation aborted without adopting it';
  end if;
  if exists(select 1 from pg_policies where schemaname='storage' and tablename='objects'
    and policyname in ('chainlab_generated_media_read','chainlab_generated_media_insert','chainlab_generated_media_delete','chainlab_generated_media_guard')) then
    raise exception 'A Chainlab media policy already exists; installation aborted without replacing it';
  end if;
end;
$guard$;

create table public.chainlab_runs (
  id uuid primary key default gen_random_uuid(),
  chain_id uuid not null references public.prompt_chains(id) on delete cascade,
  created_by uuid not null references auth.users(id),
  status text not null default 'running' check(status in ('running','completed','failed')),
  input text not null check(char_length(input) between 1 and 16000),
  outputs jsonb not null default '[]'::jsonb check(jsonb_typeof(outputs)='array' and jsonb_array_length(outputs)<=10),
  error text check(char_length(error)<=1000),
  created_at timestamptz not null default now()
);
create index chainlab_runs_chain_created_at on public.chainlab_runs(chain_id,created_at desc,id desc);
alter table public.chainlab_runs enable row level security;
revoke all on public.chainlab_runs from public,anon,authenticated;

create function public.chainlab_list_runs(p_chain_id uuid)
returns setof public.chainlab_runs language plpgsql stable security definer set search_path=''
as $$
begin
  if public.chainlab_is_superadmin() is not true then raise exception 'Superadmin access required' using errcode='42501';end if;
  if not exists(select 1 from public.prompt_chains where id=p_chain_id) then
    raise exception 'Prompt chain not found' using errcode='P0002';end if;
  return query select * from public.chainlab_runs where chain_id=p_chain_id order by created_at desc,id desc limit 50;
end;
$$;

create function public.chainlab_create_run(p_chain_id uuid,p_input text)
returns public.chainlab_runs language plpgsql security definer set search_path=''
as $$
declare v_run public.chainlab_runs;
begin
  if public.chainlab_is_superadmin() is not true then raise exception 'Superadmin access required' using errcode='42501';end if;
  if p_input is null or char_length(p_input) not between 1 and 16000 then
    raise exception 'Run input must contain 1 to 16000 characters' using errcode='22023';end if;
  perform 1 from public.prompt_chains where id=p_chain_id for key share;
  if not found then raise exception 'Prompt chain not found' using errcode='P0002';end if;
  insert into public.chainlab_runs(chain_id,created_by,input)
  values(p_chain_id,auth.uid(),p_input) returning * into v_run;
  return v_run;
end;
$$;

create function public.chainlab_update_run(p_run_id uuid,p_status text,p_outputs jsonb,p_error text)
returns public.chainlab_runs language plpgsql security definer set search_path=''
as $$
declare v_run public.chainlab_runs;v_output jsonb;v_step_id uuid;
begin
  if public.chainlab_is_superadmin() is not true then raise exception 'Superadmin access required' using errcode='42501';end if;
  select * into v_run from public.chainlab_runs where id=p_run_id for update;
  if not found then raise exception 'Run not found' using errcode='P0002';end if;
  if v_run.created_by is distinct from auth.uid() then raise exception 'Only the run creator may update it' using errcode='42501';end if;
  if p_status is null or p_status not in ('running','completed','failed')
     or p_outputs is null or jsonb_typeof(p_outputs)<>'array' then
    raise exception 'Invalid run status or outputs' using errcode='22023';end if;
  if jsonb_array_length(p_outputs)>10 or octet_length(p_outputs::text)>1000000
     or (p_status='completed' and jsonb_array_length(p_outputs)=0)
     or (p_status='failed' and (p_error is null or char_length(p_error) not between 1 and 1000))
     or (p_status<>'failed' and p_error is not null) then
    raise exception 'Invalid run result' using errcode='22023';end if;
  if v_run.status<>'running' then
    if v_run.status=p_status and v_run.outputs=p_outputs and v_run.error is not distinct from p_error then return v_run;end if;
    raise exception 'A finished run cannot be changed or reopened' using errcode='55000';end if;
  if jsonb_array_length(p_outputs)<jsonb_array_length(v_run.outputs)
     or exists(select 1 from jsonb_array_elements(v_run.outputs) with ordinality old(value,position)
       where p_outputs->((old.position-1)::integer) is distinct from old.value) then
    raise exception 'Previously saved step outputs cannot be replaced' using errcode='22023';end if;
  for v_output in select value from jsonb_array_elements(p_outputs) loop
    if jsonb_typeof(v_output)<>'object'
       or exists(select 1 from jsonb_object_keys(v_output) k where k not in ('step_id','step_name','kind','content','image_path'))
       or jsonb_typeof(v_output->'step_id') is distinct from 'string'
       or jsonb_typeof(v_output->'step_name') is distinct from 'string'
       or char_length(v_output->>'step_name') not between 1 and 120
       or jsonb_typeof(v_output->'kind') is distinct from 'string'
       or v_output->>'kind' not in ('text','image')
       or jsonb_typeof(v_output->'content') is distinct from 'string' then
      raise exception 'Invalid step output' using errcode='22023';end if;
    begin v_step_id:=(v_output->>'step_id')::uuid;
    exception when invalid_text_representation then raise exception 'Invalid step output UUID' using errcode='22023';end;
    if (v_output->>'kind'='text' and (v_output?'image_path' or char_length(v_output->>'content')=0))
       or (v_output->>'kind'='image' and (
         v_output->>'content'<>'' or jsonb_typeof(v_output->'image_path') is distinct from 'string'
         or v_output->>'image_path'<>v_run.chain_id::text||'/'||v_run.id::text||'/'||v_step_id::text||'.png')) then
      raise exception 'Images must use this run private storage path; text must contain text only' using errcode='22023';end if;
  end loop;
  if (select count(distinct value->>'step_id') from jsonb_array_elements(p_outputs))<>jsonb_array_length(p_outputs) then
    raise exception 'Each step output may be recorded only once' using errcode='22023';end if;
  update public.chainlab_runs set status=p_status,outputs=p_outputs,error=p_error where id=p_run_id returning * into v_run;
  return v_run;
end;
$$;

revoke all on function public.chainlab_list_runs(uuid),public.chainlab_create_run(uuid,text),public.chainlab_update_run(uuid,text,jsonb,text) from public,anon;
grant execute on function public.chainlab_list_runs(uuid),public.chainlab_create_run(uuid,text),public.chainlab_update_run(uuid,text,jsonb,text) to authenticated;

-- This helper exposes only a current-session boolean. Anonymous callers must
-- be able to evaluate the bucket guard without changing authorization RPC ACLs
-- or causing an execution-permission failure while reading another bucket.
create function public.chainlab_can_access_media()
returns boolean language sql stable security definer set search_path=''
as $$select public.chainlab_is_superadmin() is true;$$;
revoke all on function public.chainlab_can_access_media() from public,anon,authenticated;
grant execute on function public.chainlab_can_access_media() to anon,authenticated;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('chainlab-generated-media','chainlab-generated-media',false,20971520,array['image/png']);
-- Existing permissive policies cannot grant a nonadmin access to this bucket.
-- Every other bucket keeps exactly its prior policy behavior.
create policy chainlab_generated_media_guard on storage.objects as restrictive for all to public
using(bucket_id<>'chainlab-generated-media' or (select public.chainlab_can_access_media()))
with check(bucket_id<>'chainlab-generated-media' or (select public.chainlab_can_access_media()));
-- Existing restrictive guards still apply. The app checks Storage access before
-- an image generation request; these policies never loosen another bucket.
create policy chainlab_generated_media_read on storage.objects for select to authenticated
using(bucket_id='chainlab-generated-media' and (select public.chainlab_is_superadmin()));
create policy chainlab_generated_media_insert on storage.objects for insert to authenticated
with check(bucket_id='chainlab-generated-media' and (select public.chainlab_is_superadmin()));
create policy chainlab_generated_media_delete on storage.objects for delete to authenticated
using(bucket_id='chainlab-generated-media' and (select public.chainlab_is_superadmin()));
notify pgrst,'reload schema';


-- A read-only text projection of existing assignment history. No legacy row,
-- policy, constraint, storage object, or media URL is adopted or changed.

select pg_advisory_xact_lock(hashtext('chainlab:legacy-history-install'));
do $guard$
declare v_table text;v_column text;v_required text[];v_target text;v_count integer;
begin
  if to_regprocedure('public.chainlab_is_superadmin()') is null then
    raise exception 'Install Chainlab authorization first';end if;
  if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.proname='chainlab_list_legacy_history') then
    raise exception 'A Chainlab saved-history function already exists; installation aborted without replacing it';end if;
  foreach v_table in array array['prompt_chains','ai_generation_examples','generation_requests','generations'] loop
    if to_regclass('public.'||v_table) is null then raise exception 'Existing assignment table % is required',v_table;end if;
    v_required:=case v_table
      when 'prompt_chains' then array['id']
      when 'ai_generation_examples' then array['id','chain_id','prompt','output','is_active','created_at']
      when 'generation_requests' then array['id','chain_id','generation_id','prompt','status','model_key','source','created_at']
      else array['prompt','title','caption','model','status','created_at'] end;
    foreach v_column in array v_required loop
      if not exists(select 1 from pg_attribute where attrelid=to_regclass('public.'||v_table)
        and attname=v_column and not attisdropped and attnum>0) then
        raise exception 'Existing %.% is required; no changes made',v_table,v_column;end if;
    end loop;
  end loop;
  -- Discover the actual referenced UUID column. The generations primary key's
  -- name is deliberately not assumed, and composite/ambiguous FKs are rejected.
  select count(*),min(case when k.confrelid='public.generations'::regclass
    and cardinality(k.conkey)=1 and cardinality(k.confkey)=1 and target.atttypid='uuid'::regtype
    and source.atttypid='uuid'::regtype then target.attname end)
  into v_count,v_target
  from pg_constraint k join pg_attribute source on source.attrelid=k.conrelid and source.attname='generation_id' and source.attnum=any(k.conkey)
  left join pg_attribute target on target.attrelid=k.confrelid and target.attnum=k.confkey[1] and not target.attisdropped
  where k.contype='f' and k.conrelid='public.generation_requests'::regclass;
  if v_count<>1 or v_target is null then
    raise exception 'Expected one UUID generation_requests.generation_id foreign key to public.generations; installation aborted';end if;
end;
$guard$;

create function public.chainlab_list_legacy_history(p_chain_id uuid)
returns jsonb language plpgsql stable security definer set search_path=''
as $$
declare v_target text;v_count integer;v_result jsonb;
begin
  if public.chainlab_is_superadmin() is not true then raise exception 'Superadmin access required' using errcode='42501';end if;
  if not exists(select 1 from public.prompt_chains where id=p_chain_id) then
    raise exception 'Prompt chain not found' using errcode='P0002';end if;
  select count(*),min(case when k.confrelid='public.generations'::regclass
    and cardinality(k.conkey)=1 and cardinality(k.confkey)=1 and target.atttypid='uuid'::regtype
    and source.atttypid='uuid'::regtype then target.attname end)
  into v_count,v_target
  from pg_constraint k join pg_attribute source on source.attrelid=k.conrelid and source.attname='generation_id' and source.attnum=any(k.conkey)
  left join pg_attribute target on target.attrelid=k.confrelid and target.attnum=k.confkey[1] and not target.attisdropped
  where k.contype='f' and k.conrelid='public.generation_requests'::regclass;
  if v_count<>1 or v_target is null then
    raise exception 'The assignment generation foreign key changed; review the Chainlab saved-history setup' using errcode='55000';end if;
  execute format($query$
    select coalesce(jsonb_agg(entry order by created_at desc,source,id desc),'[]'::jsonb)
    from (
      select jsonb_build_object(
        'source','saved_example','id',e.id,'chain_id',e.chain_id,'created_at',e.created_at,
        'prompt',left(e.prompt,16000),'status',case when e.is_active then 'saved' else 'inactive' end,
        'output',left(e.output,20000),'title',null,'caption',null,'model',null,'origin',null,
        'generation_prompt',null,'generation_status',null,
        'truncated',char_length(e.prompt)>16000 or char_length(e.output)>20000
      ) as entry,e.created_at,'saved_example' as source,e.id
      from public.ai_generation_examples e where e.chain_id=$1
      union all
      select jsonb_build_object(
        'source','generation_request','id',r.id,'chain_id',r.chain_id,'created_at',r.created_at,
        'prompt',left(r.prompt,16000),'status',left(r.status,200),'output',null,
        'title',left(g.title,2000),'caption',left(g.caption,20000),
        'model',left(coalesce(g.model,r.model_key),200),'origin',left(r.source,200),
        'generation_prompt',left(g.prompt,16000),'generation_status',left(g.status,200),
        'truncated',char_length(r.prompt)>16000 or char_length(r.status)>200
          or coalesce(char_length(g.title)>2000,false) or coalesce(char_length(g.caption)>20000,false)
          or coalesce(char_length(g.prompt)>16000,false) or coalesce(char_length(g.status)>200,false)
          or coalesce(char_length(coalesce(g.model,r.model_key))>200,false) or char_length(r.source)>200
      ) as entry,r.created_at,'generation_request' as source,r.id
      from public.generation_requests r left join public.generations g on g.%I=r.generation_id
      where r.chain_id=$1
      order by created_at desc,source,id desc limit 50
    ) entries
  $query$,v_target) into v_result using p_chain_id;
  return v_result;
end;
$$;
revoke all on function public.chainlab_list_legacy_history(uuid) from public,anon;
grant execute on function public.chainlab_list_legacy_history(uuid) to authenticated;
notify pgrst,'reload schema';

commit;
